from flask import current_app, g
import os

SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS categories (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    description TEXT
);

CREATE TABLE IF NOT EXISTS posts (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    summary TEXT NOT NULL,
    content TEXT NOT NULL,
    cover_image_url TEXT,
    status TEXT NOT NULL DEFAULT 'published',
    read_time_minutes INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    category_id TEXT NOT NULL,
    FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS comments (
    id TEXT PRIMARY KEY,
    post_id TEXT NOT NULL,
    author_name TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_posts_slug ON posts (slug);
CREATE INDEX IF NOT EXISTS idx_posts_category_id ON posts (category_id);
CREATE INDEX IF NOT EXISTS idx_posts_created_at ON posts (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_categories_slug ON categories (slug);
CREATE INDEX IF NOT EXISTS idx_comments_post_id ON comments (post_id);
"""

def get_db():
    """Open or return the request-scoped SQLite connection with foreign keys enabled."""
    if "db" not in g:
        db_path = current_app.config.get("DATABASE", "chronicle.db")
        g.db = sqlite3.connect(
            db_path,
            detect_types=sqlite3.PARSE_DECLTYPES,
            check_same_thread=False
        )
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON;")
    return g.db

def close_db(e=None):
    """Close SQLite connection at the end of the request context."""
    db = g.pop("db", None)
    if db is not None:
        db.close()

def init_db(app=None):
    """Initialize schema without seeding any records."""
    if app:
        with app.app_context():
            db = get_db()
            db.executescript(SCHEMA_SQL)
            db.commit()
    else:
        db = get_db()
        db.executescript(SCHEMA_SQL)
        db.commit()

def init_app(app):
    """Register database teardown and create initial tables."""
    app.teardown_appcontext(close_db)
    init_db(app)

def row_to_dict(row):
    """Convert an sqlite3.Row instance or None to a standard Python dictionary."""
    if row is None:
        return None
    return {key: row[key] for key in row.keys()}
